/**
 * Объявление `@prisma/client` как `any` — ТОЛЬКО для проверки типов в
 * песочнице (`tsconfig.typecheck.json`), где клиент не сгенерирован:
 * `prisma generate` требует сети до binaries.prisma.sh, которой здесь
 * нет. В CI клиент есть, и там используется обычный `tsconfig.json`
 * без этого файла — настоящие типы Prisma никогда не подменяются.
 *
 * Сокращённое объявление модуля (без тела) делает любой импорт из него
 * `any`, чего достаточно, чтобы увидеть ОСТАЛЬНЫЕ ошибки типов — в
 * первую очередь в спеках, которые `ts-jest` пропускает
 * (`diagnostics: false`), а `nest build` в CI ловит.
 */
declare module '@prisma/client';
